import{_ as o,a0 as p,w as r,s as u,ao as s,I as n,x as t,a1 as l,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"5 个适用于 Linux 的流式音频播放器 | LCTT x X-CMD","titleTemplate":false,"description":"5 个适用于 Linux 的流式音频播放器 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 个适用于 Linux 的流式音频播放器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 个适用于 Linux 的流式音频播放器 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20190205 5 Streaming Audio Players for Linux","title":"5 个适用于 Linux 的流式音频播放器","tag":"202101","desc":""},"relativePath":"202101/20190205 5 Streaming Audio Players for Linux.md","filePath":"[post].md"}'),d={name:"202101/20190205 5 Streaming Audio Players for Linux.md"};function m(f,i,h,g,x,C){const e=p("Link");return r(),u("div",null,[i[18]||(i[18]=s(`<h1 id="_5-个适用于-linux-的流式音频播放器" tabindex="-1">5 个适用于 Linux 的流式音频播放器 <a class="header-anchor" href="#_5-个适用于-linux-的流式音频播放器" aria-label="Permalink to “5 个适用于 Linux 的流式音频播放器”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202101/18/220035k8mmbl1blmkb97f8.jpg" alt=""></p><p>当我工作的时候，我会一直在后台播放音乐。大多数情况下，这些音乐是以黑胶唱片的形式在转盘上旋转。但有时我不想用这种单纯的方法听音乐时，我会选择听流媒体音频应用程序的方式。然而，由于我工作在 Linux 平台上，所以我只可以使用在我的操作系统上运行良好的软件。幸运的是，对于想在 Linux 桌面听流式音频的人来说，有很多工具可以选择。</p><p>事实上，Linux 为音乐流媒体提供了许多可靠的产品，我将重点介绍我最喜欢的五种用于此任务的工具。警告一句，并不是所有的玩意都是开源的。但是如果你不介意在你的开源桌面上运行一个专有的应用程序，你有一些非常棒的选择。让我们来看看有什么可用的。</p><h3 id="spotify" tabindex="-1">Spotify <a class="header-anchor" href="#spotify" aria-label="Permalink to “Spotify”">​</a></h3><p>Linux 版的 Spotify 不是那种在你启动就闪退的愚蠢的、半生不熟的应用程序，也没有阉割什么功能。事实上，Spotify 的 Linux 版本与其他平台上的版本完全相同。使用 Spotify 流媒体客户端，你可以收听音乐和播客、创建播放列表、发现新的艺术家等等。Spotify 界面（图 1）非常易于导航和使用。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/spotify_0.jpg?itok=8-Ym-R61" alt="Spotify" title="Spotify"></p><p><em>图 1：Spotify 界面可以很容易地找到新的音乐和旧的收藏。</em></p><p>你可以使用 snap（使用 <code>sudo snap install Spotify</code> 命令）安装 Spotify，也可以使用以下命令从官方存储库安装 Spotify：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-key adv --keyserver hkp://keyserver.ubuntu.com:80 --recv-keys 931FF8E79F0876134EDDBDCCA87FF9DF48BF1C90</span></span>
<span class="line"><span>sudo echo deb http://repository.spotify.com stable non-free | sudo tee /etc/apt/sources.list.d/spotify.list</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install spotify-client</span></span></code></pre></div><p>一旦安装，你就可以登录你的 Spotify 帐户，这样你就可以开始听好听的音乐，以帮助激励你完成你的工作。如果你已在其他设备上安装了 Spotify（并登录到同一帐户），则可以指定音乐应该流式传输到哪个设备（通过单击 Spotify 窗口右下角附近的“可用设备”图标）。</p><h3 id="clementine" tabindex="-1">Clementine <a class="header-anchor" href="#clementine" aria-label="Permalink to “Clementine”">​</a></h3><p>Clementine 是 Linux 平台上最好的音乐播放器之一。Clementine 不仅允许用户播放本地存储的音乐，还可以连接到许多流媒体音频服务，例如：</p><ul><li>Amazon Cloud Drive</li><li>Box</li><li>Dropbox</li><li>Icecast</li><li>Jamendo</li><li>Magnatune</li><li>RockRadio.com</li><li>Radiotunes.com</li><li>SomaFM</li><li>SoundCloud</li><li>Spotify</li><li>Subsonic</li><li>Vk.com</li><li>或其他有趣的电台</li></ul><p>使用 Clementine 有两个注意事项。首先，你必须使用最新版本（因为某些软件库中可用的构建版本已过时，并且不会安装必要的流式处理插件）。第二，即使是最新的构建版本，一些流媒体服务也不会像预期的那样工作。例如，接入 Spotify 频道时，你只能使用最热门的曲目（而无法使用播放列表，或搜索歌曲的功能）。</p><p>使用 Clementine 互联网流媒体服务时，你会发现其中有很多你从来没有听说过的音乐家和乐队（图 2）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/clementine_0.jpg?itok=5oODJO3b" alt="Clementine" title="Clementine"></p><p><em>图 2：Clementine 互联网广播是寻找新音乐的好方法。</em></p><h3 id="odio" tabindex="-1">Odio <a class="header-anchor" href="#odio" aria-label="Permalink to “Odio”">​</a></h3>`,19)),n("p",null,[i[1]||(i[1]=t("Odio 是一个跨平台的专有应用程序（可用于 Linux、MacOS 和 Windows），它允许你流式传输各种类型的互联网音乐站。广播的内容是取自 ",-1)),l(e,{href:"http://www.radio-browser.info"},{default:a(()=>[...i[0]||(i[0]=[t("www.radio-browser.info",-1)])]),_:1}),i[2]||(i[2]=t("，而应用程序本身在为你呈现流方面做了令人难以置信的工作（图 3）。",-1))]),i[19]||(i[19]=s('<p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/odio.jpg?itok=sNPTSS3c" alt="Odio" title="Odio"></p><p><em>图 3：Odio 接口是你能找到的最好的接口之一。</em></p><p>Odio 让你很容易找到独特的互联网广播电台，甚至可以把你找到并收藏的电台添加到你的库中。目前，在 Linux 上安装 Odio 的唯一方法是通过 Snap。如果你的发行版支持 snap 软件包，请使用以下命令安装此流应用程序：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap install odio</span></span></code></pre></div><p>安装后，你可以打开应用程序并开始使用它。无需登录（或创建）帐户。Odio 的设置非常有限。实际上，它只提供了在设置窗口中选择暗色主题或亮色主题的选项。然而，尽管它可能功能有限，但 Odio 是在 Linux 上播放互联网广播的最佳选择之一。</p><h3 id="streamtuner2" tabindex="-1">StreamTuner2 <a class="header-anchor" href="#streamtuner2" aria-label="Permalink to “StreamTuner2”">​</a></h3><p>Streamtuner2 是一个优秀的互联网电台 GUI 工具。使用它，你可以流式播放以下音乐：</p><ul><li>Internet radio stations</li><li>Jameno</li><li>MyOggRadio</li><li>Shoutcast.com</li><li>SurfMusic</li><li>TuneIn</li><li>Xiph.org</li><li>YouTube</li></ul><p>Streamtuner2 提供了一个很好的界面（如果不是有点过时的话），可以很容易地找到和播放你喜爱的音乐。StreamTuner2 的一个警告是，它实际上只是一个用于查找你想要听到的流媒体的 GUI。当你找到一个站点时，双击它打开与流相关的应用程序。这意味着你必须安装必要的应用程序，才能播放流媒体。如果你没有合适的应用程序，你就不能播放流媒体。因此，你将花费大量的时间来确定要为某些流媒体安装哪些应用程序（图 4）。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/streamtuner2.jpg?itok=1MSbafWj" alt="Streamtuner2" title="Streamtuner2"></p><p><em>图4：配置 Streamtuner2 需要一个坚强的心脏。</em></p><h3 id="vlc" tabindex="-1">VLC <a class="header-anchor" href="#vlc" aria-label="Permalink to “VLC”">​</a></h3><p>很长一段时间以来，VLC 一直被称为 Linux 最好的媒体播放工具。这是有充分理由的，因为几乎所有你丢给它的东西它都能播放。其中包括流媒体广播电台。虽然你无法让 VLC 连接到 Spotify 这样的网站，但你可以直接访问互联网广播，点击播放列表，而 VLC 毫无疑问可以打开它。考虑到目前有很多互联网广播电台，你在寻找适合自己口味的音乐方面不会有任何问题。VLC 还包括可视化工具、均衡器（图 5）等工具。</p><p><img src="https://lcom.static.linuxfound.org/sites/lcom/files/vlc_0.jpg?itok=QEOsq7Ii" alt="VLC " title="VLC "></p><p><em>图 5：VLC 可视化工具和均衡器特性。</em></p><p>VLC 唯一需要注意的是，你必须有一个你希望听到的互联网广播的 URL，因为这个工具本身并不能进行管理。但是有了这些链接，你就找不到比 VLC 更好的媒体播放器了。</p><h3 id="这些工具软件怎么来的" tabindex="-1">这些工具软件怎么来的 <a class="header-anchor" href="#这些工具软件怎么来的" aria-label="Permalink to “这些工具软件怎么来的”">​</a></h3><p>如果这五个工具都不太不适合你的需要，我建议你打开你发行版的应用商店，搜索一个适合你的。有很多工具可以制作流媒体音乐、播客等等，不仅可以在 Linux 上实现，而且很简单。</p><hr>',19)),n("p",null,[i[4]||(i[4]=t("via: ",-1)),l(e,{href:"https://www.linux.com/blog/2019/2/5-streaming-audio-players-linux"},{default:a(()=>[...i[3]||(i[3]=[t("https://www.linux.com/blog/2019/2/5-streaming-audio-players-linux",-1)])]),_:1})]),n("p",null,[i[9]||(i[9]=t("作者：",-1)),l(e,{href:"https://www.linux.com/users/jlwallen"},{default:a(()=>[...i[5]||(i[5]=[t("Jack Wallen",-1)])]),_:1}),i[10]||(i[10]=t(" 选题：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...i[6]||(i[6]=[t("lujun9972",-1)])]),_:1}),i[11]||(i[11]=t(" 译者：",-1)),l(e,{href:"https://github.com/Chao-zhi"},{default:a(()=>[...i[7]||(i[7]=[t("Chao-zhi",-1)])]),_:1}),i[12]||(i[12]=t(" 校对：",-1)),l(e,{href:"https://github.com/wxy"},{default:a(()=>[...i[8]||(i[8]=[t("wxy",-1)])]),_:1})]),n("p",null,[i[15]||(i[15]=t("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...i[13]||(i[13]=[t("LCTT",-1)])]),_:1}),i[16]||(i[16]=t(" 原创编译，",-1)),l(e,{href:"https://linux.cn/"},{default:a(()=>[...i[14]||(i[14]=[t("Linux中国",-1)])]),_:1}),i[17]||(i[17]=t(" 荣誉推出",-1))])])}const y=o(d,[["render",m]]);export{k as __pageData,y as default};
